try {
  const parsed = JSON.parse(query);

  if (
    !Object.prototype.hasOwnProperty.call(parsed, "order_id") ||
    !Object.prototype.hasOwnProperty.call(parsed, "price")
  ) {
    return "Validation Failed: Missing required keys.";
  }

  return "Validation Passed: JSON is valid and complete.";

} catch (error) {
  return "Validation Failed: " + error.message;
}
